41	// Copy a BLOCK_N x HEAD_DIM tile from gmem (rows kv0..) to padded shared,
42	// zero-filling rows past seq_len. Also used to stage Q (kv0 = query row base).
43	__device__ __forceinline__ void load_tile(
44	    const __nv_bfloat16* __restrict__ src, __nv_bfloat16* __restrict__ dst,
45	    int row0, int seq_len)
46	{
47	    constexpr int CHUNKS = BLOCK_N * HEAD_DIM / 8;  // 16B chunks
48	#pragma unroll
49	    for (int i = threadIdx.x; i < CHUNKS; i += NUM_THREADS) {
50	        const int row = i / (HEAD_DIM / 8);
51	        const int col8 = i % (HEAD_DIM / 8);
52	        const int grow = row0 + row;
53	        __nv_bfloat16* s = dst + row * PADDED_D + col8 * 8;
54	        if (grow < seq_len) {
55	            cp_async16(s, src + (long long)grow * HEAD_DIM + col8 * 8);
56	        } else {
57	            *reinterpret_cast<uint4*>(s) = make_uint4(0, 0, 0, 0);
58	        }
59	    }
60	}
61	
62	__device__ __forceinline__ float warp_max4(float v) {
63	#pragma unroll
64	    for (int off = 1; off < 4; off <<= 1)
65	        v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, off));
66	    return v;
67	}
68	__device__ __forceinline__ float warp_sum4(float v) {
69	#pragma unroll
70	    for (int off = 1; off < 4; off <<= 1)
71	        v += __shfl_xor_sync(0xffffffffu, v, off);
72	    return v;
73	}
