}

int main(int argc, char** argv) {
    const int S = 64, D = 128;
    std::vector<__nv_bfloat16> qh(S*D), kh(S*D), vh(S*D);
    srand(42);
    for (auto& x : qh) x = __float2bfloat16(((rand()%2001)-1000)/1000.0f);
    for (auto& x : kh) x = __float2bfloat16(((rand()%2001)-1000)/1000.0f);
    for (auto& x : vh) x = __float2bfloat16(((rand()%2001)-1000)/1000.0f);

    __nv_bfloat16 *q, *k, *v, *out;
    float *dbg_s, *dbg_o;
    cudaMalloc(&q, S*D*2); cudaMalloc(&k, S*D*2); cudaMalloc(&v, S*D*2); cudaMalloc(&out, S*D*2);
    cudaMalloc(&dbg_s, S*S*4); cudaMalloc(&dbg_o, S*D*4);
    cudaMemset(dbg_s, 0, S*S*4); cudaMemset(dbg_o, 0, S*D*4);
    cudaMemcpy(q, qh.data(), S*D*2, cudaMemcpyHostToDevice);
    cudaMemcpy(k, kh.data(), S*D*2, cudaMemcpyHostToDevice);
    cudaMemcpy(v, vh.data(), S*D*2, cudaMemcpyHostToDevice);
    cudaFuncSetAttribute(kern, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_BYTES);
    kern<<<1, NUM_THREADS, SMEM_BYTES>>>(q, k, v, out, S, 1.0f/sqrtf(D), false, dbg_s, dbg_o);
    cudaDeviceSynchronize();
    printf("launch err: %s\n", cudaGetErrorString(cudaGetLastError()));

    // CPU reference S = Q K^T * scale (fp32)
    std::vector<float> qf(S*D), kf(S*D), vf(S*D);
    for (int i = 0; i < S*D; ++i) { qf[i] = __bfloat162float(qh[i]); kf[i] = __bfloat162float(kh[i]); vf[i] = __bfloat162float(vh[i]); }
    std::vector<float> sref(S*S, 0.f);
    for (int m = 0; m < S; ++m) for (int n = 0; n < S; ++n) {
        float acc = 0;
        for (int d = 0; d < D; ++d) acc += qf[m*D+d] * kf[n*D+d];
        sref[m*S+n] = acc / sqrtf(D);
    }
    std::vector<float> sd(S*S), od(S*D);
